// Editá esta lista: símbolo y cantidad. Los símbolos deben existir en la API.
const cartera = [
  { symbol: 'AAPL', cantidad: 10 },
  { symbol: 'GGAL', cantidad: 50 },
  { symbol: 'YPF', cantidad: 80 }
];

return [{ json: { cartera } }];

// Toma la lista del nodo "Mi cartera" y los precios de la API, y calcula el valor.
const cartera = $('Mi cartera').first().json.cartera;
const respuesta = $input.first().json;

if (!respuesta.ok || !respuesta.data || !Array.isArray(respuesta.data.tickers)) {
  throw new Error('La API no devolvió una lista de activos válida.');
}

const precios = new Map(respuesta.data.tickers.map((t) => [t.symbol, t]));
const filas = cartera.map(({ symbol, cantidad }) => {
  const ticker = precios.get(symbol);
  if (!ticker) throw new Error('El activo ' + symbol + ' no está en la muestra de la API.');
  return {
    symbol,
    cantidad,
    ultimo: ticker.last,
    valor: Math.round(cantidad * ticker.last * 100) / 100,
    cambio_pct: ticker.change_pct
  };
});

const total = Math.round(filas.reduce((suma, f) => suma + f.valor, 0) * 100) / 100;
const detalle = filas.map((f) => '- ' + f.symbol + ': ' + f.cantidad + ' u. x ' + f.ultimo + ' USD = ' + f.valor + ' USD (' + f.cambio_pct + '%)').join('\n');

return [{
  json: {
    total,
    filas,
    session: respuesta.data.session,
    texto: 'Cartera al ' + respuesta.data.session + '\n\n' + detalle + '\n\nTotal: ' + total + ' USD\n\nMuestra educativa fija de FIN·LAB. No es una recomendación de inversión.'
  }
}];
